#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

Viewpoint {
  position 0 0 4
}

NavigationInfo {
  headlight FALSE
}

Shape {
  appearance Appearance {
    material Material {
      diffuseColor 1 0 0
    }
    shaders ComposedShader {
      initializeOnly SFColor tint 0.2 0.8 0.4

      language "GLSL"
      parts [
        ShaderPart {
          url "data:x-shader/x-vertex,
attribute vec4 x3d_Vertex;
attribute vec3 x3d_Normal;
attribute vec4 x3d_TexCoord0;
attribute vec4 x3d_Color;
uniform mat4 x3d_ProjectionMatrix;
uniform mat4 x3d_ModelViewMatrix;
uniform mat3 x3d_NormalMatrix;
varying vec3 vN;
varying vec3 vP;
varying vec2 vT;
varying vec4 vC;
void main()
{
   vec4 p = x3d_ModelViewMatrix * x3d_Vertex;
   vP = p.xyz;
   vN = normalize (x3d_NormalMatrix * x3d_Normal);
   vT = x3d_TexCoord0.st;
   vC = x3d_Color;
   gl_Position = x3d_ProjectionMatrix * p;
}
"
        }
        ShaderPart {
          type "FRAGMENT"
          url "data:x-shader/x-fragment,
precision mediump float;
%23include <Nope>
varying vec3 vN;
varying vec3 vP;
varying vec2 vT;
varying vec4 vC;
uniform vec3 tint;
void main()
{
gl_FragColor = vec4 (tint * (0.3 + 0.7 * abs (vN.z)), 1.0);
}
"
        }
      ]
    }
  }
  geometry Box { }
}

